  h+='<div id="sey-rasit-note" style="font-size:var(--f-subhead);line-height:1.5;color:var(--text2);transition:opacity .18s ease;">'+esc(NOTES[rasitNoteIdx(curIdx)])+'</div>';
  h+='</div></button>';
