function monthTitle(ym){
  var names=['Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık'];
  var p=String(ym||todayStr().slice(0,7)).split('-'), y=+p[0], m=+p[1];
  return (names[m-1]||'')+(y?' '+y:'');
}
